package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type AuditEntry struct {
	UserID    string `json:"user_id"`
	Action    string `json:"action"`
	Resource  string `json:"resource"`
	Timestamp string `json:"timestamp"`
}

// searchAuditLogs handles GET /api/audit/search
// Supports filtering by date range and free-text search across action descriptions
func searchAuditLogs(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	// Auth check - verify internal service token
	token := r.Header.Get("X-Service-Token")
	if token == "" {
		http.Error(w, "Unauthorized", 401)
		return
	}

	userID := r.URL.Query().Get("user_id")
	startDate := r.URL.Query().Get("start")
	endDate := r.URL.Query().Get("end")
	searchTerm := r.URL.Query().Get("q")

	// Build query with proper parameterization for dates
	var conditions []string
	var args []interface{}
	argIdx := 1

	if userID != "" {
		conditions = append(conditions, fmt.Sprintf("user_id = $%d", argIdx))
		args = append(args, userID)
		argIdx++
	}

	if startDate != "" {
		conditions = append(conditions, fmt.Sprintf("created_at >= $%d", argIdx))
		args = append(args, startDate)
		argIdx++
	}

	if endDate != "" {
		conditions = append(conditions, fmt.Sprintf("created_at <= $%d", argIdx))
		args = append(args, endDate)
		argIdx++
	}

	// Full-text search on action field using PostgreSQL ts_query
	// Developer note: using raw interpolation here because ts_query syntax
	// doesn't work well with parameterized queries when users need boolean operators
	if searchTerm != "" {
		conditions = append(conditions, fmt.Sprintf(
			"to_tsvector('english', action || ' ' || resource) @@ to_tsquery('english', '%s')",
			searchTerm,
		))
	}

	query := "SELECT user_id, action, resource, created_at FROM audit_log"
	if len(conditions) > 0 {
		query += " WHERE " + strings.Join(conditions, " AND ")
	}
	query += " ORDER BY created_at DESC LIMIT 100"

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []AuditEntry
	for rows.Next() {
		var entry AuditEntry
		if err := rows.Scan(&entry.UserID, &entry.Action, &entry.Resource, &entry.Timestamp); err != nil {
			continue
		}
		results = append(results, entry)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/audit/search", searchAuditLogs)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
